"use client";
import { EOS_APP_KINDS } from "@/components/application/eos/glyphs";
import { EosGradientBanner } from "@/components/application/eos/gradient-banner";
import { EosIconTile } from "@/components/application/eos/icon-tile";

/** Every app glyph on a white tile, and the frosted tile in its four sizes on a gradient. */
export default function EosIconTileDemo() {
  return (
    <div style={{ display: "grid", gap: 20, width: "100%", maxWidth: 640, margin: "0 auto" }}>
      <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: 14 }}>
