          <EosIconTile key={app} app={app} label={app[0].toUpperCase() + app.slice(1)} />
        ))}
      </div>
      <EosGradientBanner gradient="lagoon" shape="card" height="auto" style={{ padding: "28px 12px" }}>
        <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", justifyContent: "center", gap: 16 }}>
          <EosIconTile app="books" tone="frosted" size="sm" />
          <EosIconTile app="books" tone="frosted" size="md" />
          <EosIconTile app="books" tone="frosted" size="lg" />
          <EosIconTile app="books" tone="frosted" size="xl" label="Coffer" />
        </div>
      </EosGradientBanner>
    </div>
  );
}

