"use client";
/**
 * EosIconTile: an app tile, white or frosted, in four sizes. White tiles carry the app's coloured glyph on a soft
 * two-layer shadow; frosted tiles are translucent glass with a light rim, a top highlight and a white glyph. A tile
 * lifts a little on hover, its deeper shadow fading in on a layer of its own; a card holding tiles lifts them on its
 * own hover, one after another (--eos-tile-i is a tile's place in the row).
 */
import type { CSSProperties, ReactNode } from "react";
import { EosAppGlyph, type EosAppKind } from "./glyphs";
import { cx } from "./shared";
import { EosScope } from "./theme";

export type EosIconTileTone = "white" | "frosted";
export type EosIconTileSize = "sm" | "md" | "lg" | "xl";

/** Side and corner scale per size; md has the token radius. */
export const EOS_TILE_SIZES: Readonly<Record<EosIconTileSize, { side: number; corner: number }>> = {
  sm: { side: 40, corner: 0.66 },
  md: { side: 60, corner: 1 },
  lg: { side: 88, corner: 1.3 },
  xl: { side: 128, corner: 1.75 },
};

const CSS = `
.eos-tile{position:relative;display:inline-grid;place-items:center;flex:none;box-sizing:border-box;width:var(--eos-tile-side);height:var(--eos-tile-side);border-radius:calc(var(--eos-radius-tile) * var(--eos-tile-corner));transition:transform var(--eos-dur-hover) var(--eos-ease);transition-delay:calc(var(--eos-tile-i, 0) * 24ms)}
.eos-tile::after{content:"";position:absolute;inset:0;border-radius:inherit;box-shadow:var(--eos-lift-shadow-sm);opacity:0;pointer-events:none;transition:opacity var(--eos-dur-hover) var(--eos-ease);transition-delay:inherit}
.eos-tile[data-tone=frosted]::after{inset:-1px}
@media (hover:hover){.eos-tile:hover{transform:translateY(var(--eos-lift-sm))}.eos-tile:hover::after{opacity:1}}
.eos-tile[data-tone=white]{background:var(--eos-tile);box-shadow:inset 0 0 0 1px var(--eos-tile-rim),var(--eos-tile-shadow)}
.eos-tile[data-tone=frosted]{color:var(--eos-frost-glyph);background:linear-gradient(180deg,rgba(255,255,255,.2),rgba(255,255,255,0) 58%),var(--eos-frost);border:1px solid var(--eos-frost-rim);-webkit-backdrop-filter:blur(var(--eos-frost-blur)) saturate(1.6);backdrop-filter:blur(var(--eos-frost-blur)) saturate(1.6);box-shadow:inset 0 1px 0 var(--eos-frost-highlight),inset 0 -1px 0 rgba(255,255,255,.08),0 12px 30px -14px rgba(24,18,64,.38)}
.eos-tile[data-tone=frosted] svg{filter:drop-shadow(0 1px 1.5px rgba(20,16,50,.14))}
.eos-tile svg{display:block}
`;

export interface EosIconTileProps {
  /** One of the fictional apps; its glyph fills the tile. */
  app?: EosAppKind;
  /** Your own glyph instead of an app's. On a frosted tile it is drawn in white (currentColor). */
  icon?: ReactNode;
  tone?: EosIconTileTone;
  size?: EosIconTileSize;
  /** An accessible name; without one the tile is decorative. */
  label?: string;
  className?: string;
  style?: CSSProperties;
}

export function EosIconTile({ app = "mail", icon, tone = "white", size = "md", label, className, style }: EosIconTileProps) {
  const { side, corner } = EOS_TILE_SIZES[size];
  const glyph = Math.round(side * 0.5);
  const vars = { "--eos-tile-side": `${side}px`, "--eos-tile-corner": String(corner) } as CSSProperties;
  return (
    <EosScope>
      <style>{CSS}</style>
      <span
        className={cx("eos-tile", className)}
        data-tone={tone}
        data-size={size}
        role={label ? "img" : undefined}
        aria-label={label}
        aria-hidden={label ? undefined : true}
        style={{ ...vars, ...style }}
      >
        {icon ?? <EosAppGlyph app={app} size={glyph} mono={tone === "frosted"} />}
      </span>
    </EosScope>
  );
}

"use client";
/**
 * Eos app glyphs: one coloured glyph per kind of fictional app, drawn on a 24 px grid, and small maker marks. In mono
 * the glyph is one colour (currentColor) with its details cut out, for frosted tiles. No brand logos.
 */
import { useId, type ReactNode } from "react";

export const EOS_APP_KINDS = ["books", "mail", "calendar", "notes", "chat", "docs", "tasks", "sheet"] as const;
export type EosAppKind = (typeof EOS_APP_KINDS)[number];

/** Each kind's colour, as drawn on a white tile. */
export const EOS_APP_COLORS: Readonly<Record<EosAppKind, string>> = {
  books: "#0E9488",
  mail: "#1D8CF0",
  calendar: "#F05A47",
  notes: "#F2B300",
  chat: "#8B5CF6",
  docs: "#4E6CF2",
  tasks: "#EE5C96",
  sheet: "#22A65A",
};

interface Paint {
  body: string;
  detail: string;
  soft: string;
}

const line = { strokeWidth: 1.8, strokeLinecap: "round" as const, fill: "none" };

const GLYPHS: Record<EosAppKind, (p: Paint) => ReactNode> = {
  books: (p) => (
    <>
      <rect x="4" y="3" width="16" height="18" rx="3.2" fill={p.body} />
      <path d="M7.2 3v18" stroke={p.soft} strokeWidth="1.6" />
      <path d="M10.5 8.5h6M10.5 12h6M10.5 15.5h3.5" stroke={p.detail} {...line} />
    </>
  ),
  mail: (p) => (
    <>
      <rect x="2.75" y="5" width="18.5" height="14" rx="3.4" fill={p.body} />
      <path d="M5.5 8.4 12 13l6.5-4.6" stroke={p.detail} {...line} strokeLinejoin="round" />
    </>
  ),
  calendar: (p) => (
    <>
      <rect x="3.5" y="4.5" width="17" height="16" rx="3.6" fill={p.body} />
      <rect x="5.4" y="9.2" width="13.2" height="9.4" rx="1.8" fill={p.detail} />
      <path d="M8.5 2.8v3.4M15.5 2.8v3.4" stroke={p.body} strokeWidth="2" strokeLinecap="round" />
      <rect x="8.1" y="11.6" width="3.2" height="3" rx="0.9" fill={p.body} />
    </>
  ),
  notes: (p) => (
    <>
      <path d="M6 3.5h9.4L20 8.1V19a1.5 1.5 0 0 1-1.5 1.5H6A1.5 1.5 0 0 1 4.5 19V5A1.5 1.5 0 0 1 6 3.5Z" fill={p.body} />
      <path d="M15.4 3.5V7a1.1 1.1 0 0 0 1.1 1.1H20" fill={p.soft} />
      <path d="M8 12h8M8 15.5h5.5" stroke={p.detail} {...line} />
    </>
  ),
  chat: (p) => (
    <>
      <path d="M5.4 4h13.2A2.4 2.4 0 0 1 21 6.4v8.2a2.4 2.4 0 0 1-2.4 2.4h-6.3l-4.6 3.5V17H5.4A2.4 2.4 0 0 1 3 14.6V6.4A2.4 2.4 0 0 1 5.4 4Z" fill={p.body} />
      <circle cx="8.3" cy="10.5" r="1.25" fill={p.detail} />
      <circle cx="12" cy="10.5" r="1.25" fill={p.detail} />
      <circle cx="15.7" cy="10.5" r="1.25" fill={p.detail} />
    </>
  ),
  docs: (p) => (
    <>
      <path d="M6.5 2.75h7.6l4.65 4.65V19.5a1.75 1.75 0 0 1-1.75 1.75H6.5A1.75 1.75 0 0 1 4.75 19.5v-15A1.75 1.75 0 0 1 6.5 2.75Z" fill={p.body} />
      <path d="M14.1 2.75v3.3c0 .75.6 1.35 1.35 1.35h3.3" fill={p.soft} />
      <path d="M8.2 11.2h7.6M8.2 14.4h7.6M8.2 17.6h4.6" stroke={p.detail} {...line} strokeWidth="1.6" />
    </>
  ),
  tasks: (p) => (
    <>
      <circle cx="12" cy="12" r="9" fill={p.body} />
      <path d="m8.1 12.3 2.6 2.6 5.3-5.6" stroke={p.detail} {...line} strokeWidth="2" strokeLinejoin="round" />
    </>
  ),
  sheet: (p) => (
    <>
      <rect x="3.5" y="3.5" width="17" height="17" rx="3.4" fill={p.body} />
      <path d="M3.9 9.2h16.2M3.9 14.8h16.2M10 9.2v11" stroke={p.detail} strokeWidth="1.5" />
    </>
  ),
};

/** A pale tint of a colour, for folds and spines. */
const tint = (hex: string) => `color-mix(in srgb, ${hex} 55%, #FFFFFF)`;

export interface EosAppGlyphProps {
  app: EosAppKind;
  size?: number;
  /** One colour (currentColor) with the details cut out, for frosted tiles. */
  mono?: boolean;
  /** Override the kind's colour. */
  color?: string;
  /** An accessible name; without one the glyph is decorative. */
  label?: string;
}

export function EosAppGlyph({ app, size = 24, mono = false, color, label }: EosAppGlyphProps) {
  const id = useId().replace(/:/g, "");
  const draw = GLYPHS[app];
  const a11y = label ? { role: "img", "aria-label": label } : { "aria-hidden": true };
  if (!mono) {
    const body = color ?? EOS_APP_COLORS[app];
    return (
      <svg width={size} height={size} viewBox="0 0 24 24" {...a11y}>
        {draw({ body, detail: "#FFFFFF", soft: tint(body) })}
      </svg>
    );
  }
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" {...a11y}>
      <mask id={`eos-glyph-${id}`} maskUnits="userSpaceOnUse" x="0" y="0" width="24" height="24">
        {draw({ body: "#FFFFFF", detail: "#000000", soft: "#B8B8B8" })}
      </mask>
      <rect width="24" height="24" fill={color ?? "currentColor"} mask={`url(#eos-glyph-${id})`} />
    </svg>
  );
}

export const EOS_MARK_KINDS = ["sun", "bars", "peak", "ring"] as const;
export type EosMarkKind = (typeof EOS_MARK_KINDS)[number];

const MARKS: Record<EosMarkKind, { bg: string; draw: ReactNode }> = {
  // A sun on the horizon: Morrow.
  sun: {
    bg: "#1E1E1D",
    draw: (
      <>
        <path d="M6.6 14.2a5.4 5.4 0 0 1 10.8 0Z" fill="#FFFFFF" />
        <path d="M5 16.6h14" stroke="#FFFFFF" strokeWidth="1.6" strokeLinecap="round" />
      </>
    ),
  },
  bars: {
    bg: "#0E9488",
    draw: <path d="M8 16.5v-4M12 16.5v-9M16 16.5v-6" stroke="#FFFFFF" strokeWidth="2.2" strokeLinecap="round" />,
  },
  peak: {
    bg: "#3E63DD",
    draw: <path d="m12 6.8 5.6 9.7H6.4Z" fill="#FFFFFF" />,
  },
  ring: {
    bg: "#E8762D",
    draw: (
      <>
        <circle cx="12" cy="12" r="5" stroke="#FFFFFF" strokeWidth="2.2" fill="none" />
        <circle cx="12" cy="12" r="1.6" fill="#FFFFFF" />
      </>
    ),
  },
};

export interface EosMarkProps {
  kind?: EosMarkKind;
  size?: number;
  /** Fill of the rounded square. */
  background?: string;
  label?: string;
}

/** A small maker mark: a glyph in a rounded square. */
export function EosMark({ kind = "sun", size = 20, background, label }: EosMarkProps) {
  const mark = MARKS[kind];
  const a11y = label ? { role: "img", "aria-label": label } : { "aria-hidden": true };
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" {...a11y}>
      <rect width="24" height="24" rx="6.5" fill={background ?? mark.bg} />
      {mark.draw}
    </svg>
  );
}

/** Morrow's sun on the horizon in one colour (currentColor), for frosted tiles. */
export function EosSunGlyph({ size = 24, label }: { size?: number; label?: string }) {
  const a11y = label ? { role: "img", "aria-label": label } : { "aria-hidden": true };
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" {...a11y}>
      <path d="M5.6 14.6a6.4 6.4 0 0 1 12.8 0Z" fill="currentColor" />
      <path d="M3.6 17.6h16.8" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <path d="M12 4.2v2M5.9 6.8l1.3 1.3M18.1 6.8l-1.3 1.3" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
    </svg>
  );
}
